function validate([heroes, monsters, coins]) {
  if (heroes.length < 1 || heroes.length > 100000) return 'heroes needs 1 to 100000 values.';
  if (monsters.length < 1 || monsters.length > 100000) return 'monsters needs 1 to 100000 values.';
  if (coins.length !== monsters.length) return 'coins needs one value per monster.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 1000000000;
  if (!heroes.every(ok) || !monsters.every(ok) || !coins.every(ok)) return 'Every power and coin value is between 1 and 10^9.';
  return null;
}

