function maximumCoins(heroes, monsters, coins) {
  const heroOrder = heroes.map((_, i) => i).sort((a, b) => heroes[a] - heroes[b]);
  const monsterOrder = monsters.map((_, j) => j).sort((a, b) => monsters[a] - monsters[b]);
  const ans = new Array(heroes.length).fill(0);
  let next = 0;
  let total = 0;
  for (const hero of heroOrder) {
    while (next < monsterOrder.length && monsters[monsterOrder[next]] <= heroes[hero]) {
      total += coins[monsterOrder[next]];
      next++;
    }
    ans[hero] = total;
  }
  return ans;
}

