function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 6);
  const m = large ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 6);
  // A narrow power range makes ties between heroes and monsters common.
  const top = large ? (rand() < 0.5 ? 1000000000 : 3000) : 1 + Math.floor(rand() * 10);
  const value = limit => 1 + Math.floor(rand() * limit);
  const heroes = Array.from({ length: n }, () => value(top));
  const monsters = Array.from({ length: m }, () => value(top));
  const coins = Array.from({ length: m }, () => value(large ? 1000000000 : 10));
  return [heroes, monsters, coins];
}
